"""Run Python code generated by the assistant in an isolated child process.

Safety measures:
- never runs without an explicit confirmation in the UI;
- separate process, own temporary working directory, time limit, output size limit;
- `-I` isolated mode (ignores user site-packages / env vars);
- a guard blocks the most dangerous modules / calls (subprocess, os.system, shutil.rmtree, sockets...)
  unless the user explicitly allowed "unrestricted" mode in Settings.
This is a best-effort sandbox, not a security boundary against malicious code.
"""
from __future__ import annotations

import os
import subprocess
import sys
import tempfile
from dataclasses import dataclass
from pathlib import Path

GUARD = r'''
import builtins, sys
_BLOCKED_MODULES = {"subprocess", "socket", "ctypes", "winreg", "_winapi", "multiprocessing", "shutil"}
_real_import = builtins.__import__
def _guarded_import(name, *a, **k):
    # only block imports written directly in the user's script (libraries keep working)
    if sys._getframe(1).f_globals.get("__name__") == "__main__" and name.split(".")[0] in _BLOCKED_MODULES:
        raise ImportError(f"[DOUBAJ sandbox] module '{name}' is blocked")
    return _real_import(name, *a, **k)
builtins.__import__ = _guarded_import
import os as _os
for _n in ("system", "popen", "startfile", "kill", "execv", "execve"):
    if hasattr(_os, _n):
        setattr(_os, _n, lambda *a, **k: (_ for _ in ()).throw(PermissionError("[DOUBAJ sandbox] blocked")))
_real_open = builtins.open
_ROOT = _os.path.abspath(_os.getcwd())
def _guarded_open(file, mode="r", *a, **k):
    p = _os.path.abspath(str(file))
    if any(m in mode for m in "wax+") and not p.startswith(_ROOT):
        raise PermissionError("[DOUBAJ sandbox] writing outside the sandbox folder is blocked")
    return _real_open(file, mode, *a, **k)
builtins.open = _guarded_open
'''


@dataclass
class RunResult:
    stdout: str
    stderr: str
    returncode: int
    timed_out: bool
    workdir: str


def python_command() -> list[str]:
    """In the frozen EXE there is no python.exe: the EXE itself runs scripts with --run-python."""
    if getattr(sys, "frozen", False):
        return [sys.executable, "--run-python"]
    return [sys.executable, "-I"]


def run_python(code: str, timeout: int = 30, restricted: bool = True, files: dict[str, str] | None = None) -> RunResult:
    work = Path(tempfile.mkdtemp(prefix="doubaj_run_"))
    for name, content in (files or {}).items():
        p = work / name
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(content, encoding="utf-8")
    script = work / "main_doubaj.py"
    script.write_text((GUARD if restricted else "") + "\n" + code, encoding="utf-8")
    env = {k: v for k, v in os.environ.items() if not k.upper().endswith(("KEY", "TOKEN", "SECRET"))}
    env["PYTHONIOENCODING"] = "utf-8"
    env["MPLBACKEND"] = "Agg"
    creationflags = 0x08000000 if sys.platform.startswith("win") else 0  # CREATE_NO_WINDOW
    try:
        p = subprocess.run(python_command() + [str(script)], cwd=str(work), capture_output=True, text=True,
                           encoding="utf-8", errors="replace", timeout=timeout, env=env, creationflags=creationflags)
        return RunResult(p.stdout[-20000:], p.stderr[-20000:], p.returncode, False, str(work))
    except subprocess.TimeoutExpired as e:
        return RunResult((e.stdout or "")[-20000:] if isinstance(e.stdout, str) else "",
                         f"Timeout after {timeout}s", -1, True, str(work))


def run_script_entry(path: str) -> None:
    """Entry used by the frozen EXE: DOUBAJ AI.exe --run-python script.py"""
    import runpy
    # windowed EXE: make sure stdout/stderr exist (inherited pipes from the parent process)
    for name, fd in (("stdout", 1), ("stderr", 2)):
        if getattr(sys, name) is None:
            try:
                setattr(sys, name, open(fd, "w", encoding="utf-8", errors="replace", closefd=False, buffering=1))
            except OSError:
                setattr(sys, name, open(os.devnull, "w"))
    sys.argv = [path]
    os.chdir(os.path.dirname(os.path.abspath(path)))
    runpy.run_path(path, run_name="__main__")
